package contextindex

import (
	"context"
	"strings"
	"testing"
)

// AMAP-V0-245: the exported admission rules agree with the index BuildRevisionContext builds, so
// the application map's incremental build can tell from two blobs that an edit leaves the source
// set as it was.
func TestAMAPV0245AdmissionRulesMatchIndex(t *testing.T) {
	files := map[string]string{
		"app/util.js":       "export const one = 1;\n",
		"app/gen.js":        "// Code generated by gen. DO NOT EDIT.\nexport const two = 2;\n",
		"app/big.js":        strings.Repeat("x", SourceSizeBound+1),
		"assets/logo.png":   "png",
		"node_modules/a.js": "export const a = 1;\n",
	}
	root := impactRepositoryWithFiles(t, files)
	revision := strings.TrimSpace(testGit(t, root, "rev-parse", "HEAD"))
	index, err := BuildRevisionContext(context.Background(), root, revision)
	if err != nil {
		t.Fatal(err)
	}
	for p, content := range files {
		_, indexed := index.Sources[p]
		if got := SourceAdmitted(p, []byte(content)); got != indexed {
			t.Errorf("SourceAdmitted(%s) = %v, index has it: %v", p, got, indexed)
		}
	}
	if !SourcePathAdmitted("app/gen.js") || SourcePathAdmitted("node_modules/a.js") {
		t.Error("SourcePathAdmitted disagrees with the path rule")
	}
	if err := CheckRevisionAdmission(context.Background(), root, revision); err != nil {
		t.Fatalf("CheckRevisionAdmission: %v", err)
	}
	if err := CheckRevisionAdmission(context.Background(), root, strings.Repeat("0", len(revision))); err == nil {
		t.Fatal("CheckRevisionAdmission accepted an absent revision")
	}
	for text, want := range map[string]bool{
		"{}":                                     true,
		"// comment\n{\"compilerOptions\": {},}": true,
		"null":                                   true,
		"export const one = 1;\n":                false,
		"{ a: 1 }":                               false,
	} {
		if got := WebConfigShaped([]byte(text)); got != want {
			t.Errorf("WebConfigShaped(%q) = %v, want %v", text, got, want)
		}
	}
}
